/* From Uiverse.io by PriyanshuGupta28 - Tags: form, subscriptions card, email card */
/* Unique styles for the newsletter form */
.__UIV_SCOPE__ .newsletter-form {
  max-width: 400px;
  margin: 0 auto;
  padding: 20px;
  border: 2px solid #333;
  border-radius: 8px;
  background-color: #f7f7f7;
  font-family: Arial, sans-serif;
  box-shadow: rgba(0, 0, 0, 0.3) 0px 19px 38px, rgba(0, 0, 0, 0.22) 0px 15px 12px;
}

.__UIV_SCOPE__ .heading {
  font-weight: bold;
  font-size: 20px;
}

.__UIV_SCOPE__ .newsletter-form h2 {
  margin-top: 0;
  color: #333;
  font-size: 24px;
}

.__UIV_SCOPE__ .newsletter-form label {
  display: block;
  font-weight: bold;
  color: #666;
  margin-bottom: 10px;
}

.__UIV_SCOPE__ .newsletter-form input[type="email"] {
  width: 100%;
  padding: 10px;
  margin-bottom: 10px;
  border: 1px solid #ccc;
  border-radius: 4px;
}

.__UIV_SCOPE__ .newsletter-form input[type="submit"] {
  width: 100%;
  padding: 10px;
  border: none;
  border-radius: 4px;
  background-color: #ff6600;
  color: #fff;
  font-weight: bold;
  cursor: pointer;
}

.__UIV_SCOPE__ .newsletter-form input[type="submit"]:hover {
  background-color: #ff8533;
}
